void Solver::bump_var(int var, double coeff) {
    double bump = var_inc * coeff;
    activity[var] += bump;

    // Exponential decay for stability
    if (activity[var] > 1e50) {
        for (int i = 1; i <= vars; i++) {
            activity[i] *= 1e-50;
        }
        var_inc *= 1e-50;
    }

    // Adaptive bump based on recent conflict participation
    if (conflicts > 1000) {
        double conflict_rate = (double)conflicts / (trail.size() + 1);
        if (conflict_rate > 0.1 && coeff > 0.8) {
            activity[var] += bump * 0.3;
        }
    }

    if (vsids.inHeap(var)) vsids.update(var);
}
